1002	/**
1003	 * Exported ONLY so `test/migration-gate.test.ts` can run `sh -n` over the result.
1004	 *
1005	 * This is ~120 lines of shell assembled from a TypeScript array of string
1006	 * fragments, with three levels of quoting (TS string → shell double-quote →
1007	 * embedded Go template in single quotes). A quoting mistake in here does not fail
1008	 * a typecheck, does not fail a build, and does not fail a lint — it fails on a
1009	 * customer's live server, mid-cutover, as an empty inventory that the engine then
1010	 * reads as "this machine has nothing on it". Generated shell nobody parses is
1011	 * generated shell nobody has checked.
1012	 */
1013	export function srcInventoryScript(priv: string): string {
1014	  return [
1015	    "export LC_ALL=C",
1016	    'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
1017	    'PRIV="' + priv + '"',
1018	    // One Go template that emits every container field we can safely reproduce,
1019	    // one "key value" per line. Optional strings emit "-" so whitespace-splitting
1020	    // stays aligned.
1021	    "FMT='name {{.Name}}",
1022	    "image {{.Config.Image}}",
1023	    "state {{.State.Status}}",
1024	    "restart {{.HostConfig.RestartPolicy.Name}}",
1025	    "netmode {{.HostConfig.NetworkMode}}",
1026	    "runuser {{.Config.User}}",
1027	    "workdir {{.Config.WorkingDir}}",
1028	    "privileged {{.HostConfig.Privileged}}",
1029	    // `{{len .HostConfig.Devices}}` on its own aborts the WHOLE template when the
1030	    // field is absent ("len of nil pointer") — and docker then writes nothing to
1031	    // stdout and exits non-zero, so with `2>/dev/null` the container produced zero
1032	    // lines and vanished from the inventory entirely. Guarding with `if` keeps a
1033	    // device-less container readable instead of unreadable.
1034	    "devices {{if .HostConfig.Devices}}{{len .HostConfig.Devices}}{{else}}0{{end}}",
1035	    "caps {{range .HostConfig.CapAdd}}{{.}} {{end}}",
