1771	/**
1772	 * Turn one inspected source container into a plan we are willing to execute, or
1773	 * into a list of BLOCKERS explaining why we will not.
1774	 *
1775	 * The rule is absolute: a value either passes its allowlist and goes into the
1776	 * command, or the whole container is refused and logged. Nothing is sanitized,
1777	 * nothing arbitrary is ever executed. That is why an overridden Cmd/Entrypoint
1778	 * is a blocker — re-tokenising a shell string safely is not possible, so we say
1779	 * so instead of guessing.
1780	 */
1781	function planContainer(c: SrcContainer): ContainerPlan {
1782	  const blockers: string[] = [];
1783	  const plan: ContainerPlan = {
1784	    name: c.name, image: c.image, restart: "unless-stopped", ports: [], binds: [], volumes: [],
1785	    network: "", hostNetwork: false, runuser: "", workdir: "", privileged: false, caps: [], blockers,
1786	  };
1787	
1788	  if (!CONTNAME_RE.test(c.name)) blockers.push("container name is not reproducible safely");
1789	  if (!validImageRef(c.image)) blockers.push("image reference is not reproducible safely");
1790	
1791	  // Restart policy: keep the source's, but upgrade "no"/unset to unless-stopped
1792	  // so a reboot of the new server does not take the site down.
1793	  plan.restart = RESTART_POLICIES.has(c.restart) && c.restart !== "no" ? c.restart : "unless-stopped";
1794	
1795	  // Cmd / Entrypoint overrides cannot be re-tokenised safely.
1796	  if (c.cmd !== c.imagecmd) blockers.push("it runs a custom command (docker run … <cmd>)");
1797	  if (c.entrypoint !== c.imageentrypoint) blockers.push("it runs a custom entrypoint");
1798	  if (c.devices > 0) blockers.push(`it maps ${c.devices} host device(s)`);
1799	
1800	  for (const p of c.ports) {
1801	    if (plan.ports.length >= 20) break;
1802	    if (p.hostIp && !IPV4_RE.test(p.hostIp)) {
1803	      blockers.push("a published port binds to an address we cannot validate");
1804	      break;
1805	    }
1806	    plan.ports.push(p);
1807	  }
1808	
1809	  for (const m of c.mounts) {
1810	    if (m.kind === "bind") {
1811	      if (!validPath(m.source) || !validPath(m.dest)) {
1812	        blockers.push(`bind mount ${clean(m.dest, 60) || "?"} uses a path we cannot validate`);
1813	        continue;
1814	      }
1815	      plan.binds.push({ src: m.source, dest: m.dest, ro: !m.rw });
1816	    } else if (m.kind === "volume") {
