1828	  // container:<id> sharing and multi-attach are not.
1829	  if (c.netmode === "host") {
1830	    plan.hostNetwork = true;
1831	  } else if (c.netmode.startsWith("container:")) {
1832	    blockers.push("it shares another container's network namespace");
1833	  } else {
