1839	    }
1840	  }
1841	
1842	  if (c.runuser) {
1843	    if (RUNUSER_RE.test(c.runuser)) plan.runuser = c.runuser;
1844	    else blockers.push("its run-as user is not reproducible safely");
1845	  }
1846	  if (c.workdir && c.workdir !== "/") {
