1848	    else blockers.push("its working directory is not reproducible safely");
1849	  }
1850	  plan.privileged = c.privileged;
1851	  for (const cap of c.caps) {
1852	    if (plan.caps.length >= 20) break;
1853	    if (CAP_RE.test(cap)) plan.caps.push(cap);
1854	    else blockers.push("it adds a Linux capability we cannot validate");
1855	  }
1856	  return plan;
