export function cleanRows(s: unknown, max: number): string[] {
  return cleanLines(s, max)
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);
}

/** A Docker image reference we are willing to put in a command at all. */
function validImageRef(r: string): boolean {
  return (
    typeof r === "string" &&
    IMAGEREF_RE.test(r) &&
    !r.includes("..") &&
    !r.includes("//") &&
    !r.startsWith("-") &&
    !r.includes("<none>")
  );
}

